 50	/// Metadata key holding the JSON-encoded [`CoordinatorHandoff`].
 51	pub(crate) const HANDOFF_METADATA_KEY: &str = "coordinator.handoff";
 52	
 53	/// Upper bound on a handoff body. A handoff is a brief — operator-stated
 54	/// facts, decisions, open threads, prohibitions — not a transcript
 55	/// replay; the cap is what keeps it that way when a session is tempted to
 56	/// dump everything it knows.
 57	pub(crate) const MAX_HANDOFF_BYTES: usize = 16 * 1024;
 58	
 59	/// Filename of the session-start brief, written under the coordinator
 60	/// session directory's `.claude/` (next to the app-managed
 61	/// `settings.local.json`) and handed to `claude` as its initial prompt.
 62	pub(crate) const START_BRIEF_FILENAME: &str = "handoff-brief.txt";
 63	
 64	/// The stored handoff record.
 65	#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
 66	pub(crate) struct CoordinatorHandoff {
 67	    pub(crate) body: String,
 68	    /// Unix epoch seconds.
 69	    pub(crate) written_at: i64,
 70	    /// Spawn token of the coordinator record that was live at write time.
 71	    /// Empty when no coordinator record existed (a handoff written from a
 72	    /// plain terminal before any coordinator ever ran).
 73	    pub(crate) writer_spawn_token: String,
 74	}
 75	
 76	/// What the engine found when it looked for a handoff. `Missing` and
 77	/// `Unreadable` are deliberately separate variants: "no session ever wrote
 78	/// one" and "one was written but the engine cannot read it back" call for
 79	/// different operator responses, and collapsing them would hide the
 80	/// second behind the first.
 81	#[derive(Debug, Clone, PartialEq, Eq)]
 82	pub(crate) enum HandoffState {
 83	    Present(CoordinatorHandoff),
 84	    Missing,
 85	    Unreadable(String),
 86	}
 87	
 88	impl HandoffState {
 89	    /// Short label for the engine-audit log.
 90	    pub(crate) fn audit_outcome(&self) -> &'static str {
 91	        match self {
 92	            Self::Present(_) => "present",
 93	            Self::Missing => "missing",
 94	            Self::Unreadable(_) => "unreadable",
 95	        }
 96	    }
 97	}
 98	
 99	/// Why a fresh coordinator session is being created. Rendered into the
100	/// session-start brief so the incoming session can tell the operator what
101	/// ended the previous one — a crash and an operator reset warrant
102	/// different first replies.
103	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
104	pub(crate) enum CoordinatorStartReason {
105	    /// No coordinator record existed: the first session on this engine.
106	    FirstCreation,
107	    /// The recorded tmux session no longer exists (tmux server restart,
108	    /// session killed, or a crash window between intent and creation).
109	    SessionMissing,
110	    /// The tmux session survived but its `claude` process exited — a
111	    /// crash, `/exit`, or a Claude Code update that ended the process.
112	    PaneDead,
113	    /// An explicit UI-confirmed recreate (model mismatch or operator reset,
114	    /// the latter also being how a `claude` update is picked up).
115	    Recreate(CoordinatorRecreateReason),
116	}
117	
118	impl CoordinatorStartReason {
119	    fn describe(self) -> &'static str {
120	        match self {
121	            Self::FirstCreation => "this is the first coordinator session on this engine",
122	            Self::SessionMissing => {
123	                "the previous coordinator's tmux session no longer existed (tmux server restart, session \
124	                 killed, or an engine crash mid-create)"
125	            }
126	            Self::PaneDead => {
127	                "the previous coordinator's claude process exited (a crash, `/exit`, or a Claude Code update \
128	                 ending the process) while its tmux session survived"
129	            }
130	            Self::Recreate(CoordinatorRecreateReason::ModelMismatch) => {
131	                "the operator confirmed replacing the previous coordinator to change its model"
132	            }
133	            Self::Recreate(CoordinatorRecreateReason::OperatorReset) => {
134	                "the operator explicitly reset the coordinator (typically to pick up a Claude Code update or \
135	                 clear context)"
136	            }
137	        }
138	    }
139	
140	    pub(crate) fn audit_label(self) -> &'static str {
141	        match self {
142	            Self::FirstCreation => "first_creation",
143	            Self::SessionMissing => "session_missing",
144	            Self::PaneDead => "pane_dead",
145	            Self::Recreate(CoordinatorRecreateReason::ModelMismatch) => "recreate_model_mismatch",
146	            Self::Recreate(CoordinatorRecreateReason::OperatorReset) => "recreate_operator_reset",
147	        }
148	    }
149	}
