151	/// Identity of the coordinator session a fresh one replaces, captured
152	/// from the metadata record *before* the new spawn intent overwrites it.
153	#[derive(Debug, Clone, PartialEq, Eq)]
154	pub(crate) struct PreviousSession {
155	    pub(crate) spawn_token: String,
156	    pub(crate) spawned_at: Option<i64>,
157	}
158	
159	impl From<&CoordinatorTmuxRecord> for PreviousSession {
160	    fn from(record: &CoordinatorTmuxRecord) -> Self {
161	        Self {
162	            spawn_token: record.spawn_token.clone(),
163	            spawned_at: record.spawned_at,
164	        }
165	    }
166	}
167	
168	impl WorkDb {
169	    /// Read the stored handoff. Never errors: every failure mode is a
170	    /// [`HandoffState`] variant so callers cannot accidentally treat a
171	    /// read failure as "nothing stored".
172	    pub(crate) fn coordinator_handoff_state(&self) -> HandoffState {
173	        match self.get_metadata(HANDOFF_METADATA_KEY) {
174	            Ok(None) => HandoffState::Missing,
175	            Ok(Some(raw)) => match serde_json::from_str::<CoordinatorHandoff>(&raw) {
176	                Ok(handoff) => HandoffState::Present(handoff),
177	                Err(error) => {
178	                    HandoffState::Unreadable(format!("stored coordinator handoff is not valid JSON: {error}"))
179	                }
180	            },
181	            Err(error) => HandoffState::Unreadable(format!("could not read stored coordinator handoff: {error:#}")),
182	        }
183	    }
184	
185	    /// Replace the stored handoff. `body` must already have passed
186	    /// [`validate_handoff_body`].
187	    pub(crate) fn set_coordinator_handoff(
188	        &self,
189	        body: &str,
190	        writer_spawn_token: &str,
191	        now_epoch_secs: i64,
192	    ) -> Result<CoordinatorHandoff> {
193	        let handoff = CoordinatorHandoff {
194	            body: body.to_owned(),
195	            written_at: now_epoch_secs,
196	            writer_spawn_token: writer_spawn_token.to_owned(),
197	        };
198	        let raw = serde_json::to_string(&handoff).context("encoding coordinator handoff")?;
199	        self.set_metadata(HANDOFF_METADATA_KEY, &raw)
200	            .context("persisting coordinator handoff")?;
201	        Ok(handoff)
202	    }
203	}
204	
205	/// Normalize and bound a handoff body. Returns the trimmed body, or the
206	/// operator-facing reason it was refused.
207	pub(crate) fn validate_handoff_body(body: &str) -> std::result::Result<String, String> {
208	    let trimmed = body.trim();
209	    if trimmed.is_empty() {
210	        return Err(
211	            "coordinator handoff body is empty; write the operator-stated facts, decisions, open threads, \
212	                    and prohibitions the next session must know (see \"Session handoff\" in the coordinator prompt)"
213	                .to_owned(),
214	        );
215	    }
216	    if trimmed.len() > MAX_HANDOFF_BYTES {
217	        return Err(format!(
218	            "coordinator handoff body is {} bytes; the cap is {MAX_HANDOFF_BYTES}. A handoff is a brief, not a \
219	             transcript: keep operator-stated facts, decisions, open threads, and prohibitions; drop narrative",
220	            trimmed.len()
221	        ));
222	    }
223	    Ok(trimmed.to_owned())
224	}
225	
226	/// Wire view of a stored handoff, judged against the coordinator record
227	/// that is live *now*.
228	pub(crate) fn handoff_view(
229	    handoff: &CoordinatorHandoff,
230	    current_spawn_token: Option<&str>,
231	    now_epoch_secs: i64,
232	) -> CoordinatorHandoffView {
233	    CoordinatorHandoffView::builder()
234	        .age_secs(now_epoch_secs.saturating_sub(handoff.written_at))
235	        .body(handoff.body.clone())
236	        .writer_spawn_token(handoff.writer_spawn_token.clone())
237	        .written_at(handoff.written_at)
238	        .written_at_iso8601(format_epoch_iso8601(handoff.written_at))
239	        .written_by_current_session(
240	            !handoff.writer_spawn_token.is_empty() && current_spawn_token == Some(handoff.writer_spawn_token.as_str()),
241	        )
242	        .build()
243	}
244	
245	/// Everything [`compose_start_brief`] needs; kept as a struct so the
246	/// composer stays pure and directly testable.
247	pub(crate) struct StartBriefInputs<'a> {
248	    pub(crate) state: &'a HandoffState,
249	    pub(crate) previous: Option<&'a PreviousSession>,
250	    pub(crate) reason: CoordinatorStartReason,
251	    pub(crate) now_epoch_secs: i64,
252	    /// Directory holding prior sessions' Claude Code transcripts, when the
253	    /// caller verified it exists. Mentioned as a slow last resort only.
254	    pub(crate) transcript_dir: Option<&'a Path>,
255	}
256	
257	fn when(epoch: i64, now: i64) -> String {
258	    match format_elapsed_ago(epoch, now) {
259	        Some(ago) => format!("{ago} ({})", format_epoch_iso8601(epoch)),
260	        None => format_epoch_iso8601(epoch),
261	    }
262	}
263	
264	/// Render the session-start brief handed to a fresh coordinator session
265	/// as its initial prompt. Pure over its inputs.
266	pub(crate) fn compose_start_brief(inputs: StartBriefInputs<'_>) -> String {
267	    let StartBriefInputs {
268	        state,
269	        previous,
270	        reason,
271	        now_epoch_secs: now,
272	        transcript_dir,
273	    } = inputs;
274	    let mut out = String::new();
275	    out.push_str("[Boss coordinator session start: automatic handoff brief from the engine]\n\n");
276	    out.push_str(&format!(
277	        "You are a fresh coordinator session; {}. Everything the operator told the previous session is gone from \
278	         your context. What follows is the engine's report on the session handoff.\n\n",
279	        reason.describe()
280	    ));
281	
282	    let previous_started = previous.and_then(|p| p.spawned_at).map(|at| when(at, now));
283	    let previous_phrase = match (&previous_started, previous) {
284	        (Some(started), _) => format!("the session that just ended (started {started})"),
285	        (None, Some(_)) => "the session that just ended".to_owned(),
286	        (None, None) => "the previous session".to_owned(),
287	    };
288	
289	    match state {
290	        HandoffState::Present(handoff) => {
291	            let written = when(handoff.written_at, now);
292	            let by_previous =
293	                previous.is_some_and(|p| !p.spawn_token.is_empty() && p.spawn_token == handoff.writer_spawn_token);
294	            if by_previous {
295	                out.push_str(&format!(
296	                    "HANDOFF PRESENT: written by {previous_phrase}, {written}. Facts in it are current as of that \
297	                     time, not now.\n"
298	                ));
299	            } else if handoff.writer_spawn_token.is_empty() {
300	                out.push_str(&format!(
301	                    "HANDOFF PRESENT (writer unknown): a handoff was written {written}, but the engine has no record \
302	                     of the session that wrote it. Treat it as possibly stale and confirm its facts with the \
303	                     operator.\n"
304	                ));
305	            } else if previous.is_some() {
306	                out.push_str(&format!(
307	                    "HANDOFF STALE: {previous_phrase} never wrote a handoff. The newest handoff, below, was written \
308	                     by an EARLIER session, {written}. Everything the operator told the session that just ended is \
309	                     NOT in it. Say so in your first reply and ask the operator what changed since then before \
310	                     relying on any of it.\n"
311	                ));
312	            } else {
313	                out.push_str(&format!(
314	                    "HANDOFF PRESENT (writer unknown): a handoff was written {written}, but the engine has no record \
315	                     of the session that wrote it. Treat it as possibly stale and confirm its facts with the \
316	                     operator.\n"
317	                ));
318	            }
319	            out.push_str("--- handoff begins ---\n");
320	            out.push_str(handoff.body.trim_end());

