264	/// Recreate the coordinator after an explicit UI confirmation — either a
265	/// model-mismatch replacement or an operator-initiated reset. The expected
266	/// token prevents a delayed confirmation from killing a newer session
267	/// created by a concurrent restart recovery. `reason` is recorded to the
268	/// audit log so a manual reset is distinguishable there both from the
269	/// automatic model-mismatch path and from a crash/session-loss restart
270	/// (`restart_if_dead`/`reconcile_existing`), neither of which audits this
271	/// event at all.
272	pub(crate) async fn recreate_after_confirmation(
273	    spawn: &CoordinatorSpawn<'_>,
274	    expected_spawn_token: &str,
275	    reason: CoordinatorRecreateReason,
276	) -> Result<CoordinatorTmuxRecord> {
277	    let result = recreate_after_confirmation_inner(spawn, expected_spawn_token, reason).await;
278	    match &result {
279	        Ok(record) => audit::record_event(
280	            "coordinator_recreate",
281	            &json!({
282	                "outcome": "success",
283	                "reason": reason,
284	                "old_spawn_token": expected_spawn_token,
285	                "new_spawn_token": record.spawn_token,
286	            }),
287	        ),
288	        Err(error) => audit::record_event(
289	            "coordinator_recreate",
290	            &json!({
291	                "outcome": "failed",
292	                "reason": reason,
293	                "old_spawn_token": expected_spawn_token,
294	                "error": format!("{error:#}"),
295	            }),
296	        ),
297	    }
298	    result
