436	/// Resolve which tmux server currently hosts the coordinator session:
437	/// `socket_tmux` (the durable `-S` socket) unless a live
438	/// [`COORDINATOR_SESSION_NAME`] session survives on the pre-move `-L boss`
439	/// server, in which case `legacy_tmux`.
440	///
441	/// Every coordinator lifecycle entry point (`ensure_for_attach`,
442	/// `restart_if_dead`, `recreate_after_confirmation`) takes a single `&Tmux`
443	/// and, before this routing existed, every caller always passed the socket
444	/// handle. That meant `session_exists(tmux, ...)` reported "absent" for a
445	/// coordinator the boot-time drain had adopted on the legacy server (it
446	/// lives on a different server entirely), so the supervisor's restart loop
447	/// would spawn a brand-new coordinator on the socket on top of the still-live
448	/// legacy one — two agents driving the same `state.db`. Calling this once,
449	/// before invoking any lifecycle function, and passing its result through
450	/// for that call routes every check (`session_exists`, `show_environment`,
451	/// `kill_session_verified`, `new_session`) at the server that actually holds
452	/// the session, so the legacy coordinator is recovered/replaced in place
453	/// rather than shadowed by a second one.
454	///
455	/// `legacy_tmux` is `None` when the caller could not build a legacy handle
456	/// (e.g. no resolved tmux executable yet) — in that case this always
457	/// returns `socket_tmux`, matching the engine's pre-migration behavior.
458	pub(crate) async fn resolve_active_handle<'a>(socket_tmux: &'a Tmux, legacy_tmux: Option<&'a Tmux>) -> &'a Tmux {
459	    let Some(legacy) = legacy_tmux else {
460	        return socket_tmux;
461	    };
462	    match session_exists(legacy, COORDINATOR_SESSION_NAME).await {
463	        Ok(true) => {
464	            tracing::warn!(
465	                "coordinator tmux: a live coordinator session survives on the pre-move -L boss server; \
466	                 routing this lifecycle call through it instead of the durable socket so the engine does \
467	                 not spawn a second live coordinator on top of it",
468	            );
469	            legacy
470	        }
471	        Ok(false) => socket_tmux,
472	        Err(err) => {
473	            tracing::warn!(
474	                error = %format!("{err:#}"),
475	                "coordinator tmux: failed to probe the legacy -L boss server for a surviving coordinator \
476	                 session (best-effort); assuming it is not there",
477	            );
478	            socket_tmux
479	        }
480	    }
481	}
