529	/// A coordinator session just created by [`start_new`] already has the
530	/// current prompt, so its nudge baseline is seeded to match — otherwise
531	/// the very next adoption of this same session would spuriously nudge it
532	/// to re-read the instructions it just started with. Best-effort: a
533	/// failure here costs one avoidable nudge later, never a wrong or lost
534	/// one, so it must never fail session creation.
535	fn seed_prompt_nudge_baseline(work_db: &WorkDb, working_directory: &Path) {
536	    match hash_rendered_prompt(working_directory) {
537	        Ok(hash) => {
538	            if let Err(error) = work_db.set_metadata(PROMPT_NUDGE_HASH_KEY, &hash) {
539	                tracing::warn!(
540	                    error = %format!("{error:#}"),
541	                    "coordinator prompt nudge: failed to seed baseline hash for freshly created session"
542	                );
543	            }
544	        }
545	        Err(error) => {
546	            tracing::warn!(
547	                error = %format!("{error:#}"),
548	                "coordinator prompt nudge: failed to hash rendered prompt while seeding baseline"
549	            );
550	        }
551	    }
552	}
553	
554	/// Nudge an *adopted* coordinator session to re-read its instructions when
555	/// the rendered prompt has changed since the last successfully sent
556	/// nudge. Best-effort and non-fatal by design: this must never fail the
557	/// attach flow adoption is part of. A send failure is recorded via
558	/// `tracing` and the engine-audit log, and the stored hash is left
559	/// unchanged so the next restart's adoption retries rather than silently
560	/// dropping the change. `send_keys` succeeding only proves tmux accepted
561	/// the bytes into the pane pty — not that the coordinator treated them as
562	/// a pending prompt — so audit/log outcomes use `"sent"`, not `"delivered"`.
563	async fn maybe_nudge_prompt_change(
564	    work_db: &WorkDb,
565	    tmux: &Tmux,
566	    record: &CoordinatorTmuxRecord,
567	    working_directory: &Path,
568	) {
569	    let current_hash = match hash_rendered_prompt(working_directory) {
570	        Ok(hash) => hash,
571	        Err(error) => {
572	            let error = format!("{error:#}");
573	            tracing::error!(
574	                error = %error,
575	                "coordinator prompt nudge: could not hash rendered prompt; skipping"
576	            );
577	            audit::record_event(
578	                "coordinator_prompt_nudge",
579	                &json!({
580	                    "outcome": "skipped",
581	                    "reason": "hash_unavailable",
582	                    "error": error,
583	                }),
584	            );
585	            return;
586	        }
587	    };
588	    let last_nudged_hash = match work_db.get_metadata(PROMPT_NUDGE_HASH_KEY) {
589	        Ok(value) => value,
590	        Err(error) => {
591	            let error = format!("{error:#}");
592	            tracing::warn!(
593	                error = %error,
594	                "coordinator prompt nudge: could not read last-nudged hash; skipping"
595	            );
596	            audit::record_event(
597	                "coordinator_prompt_nudge",
598	                &json!({
599	                    "outcome": "skipped",
600	                    "reason": "metadata_unavailable",
601	                    "error": error,
602	                }),
603	            );
604	            return;
605	        }
606	    };
607	    let Some(last_nudged_hash) = last_nudged_hash else {
608	        // No recorded baseline: a live session from before this feature
609	        // (or a failed seed) gives no evidence the prompt changed, so
610	        // establish the current hash and do not send.
611	        if let Err(error) = work_db.set_metadata(PROMPT_NUDGE_HASH_KEY, &current_hash) {
612	            tracing::warn!(
613	                error = %format!("{error:#}"),
614	                "coordinator prompt nudge: failed to seed baseline hash for session with no recorded baseline"
615	            );
616	        }
617	        return;
618	    };
619	    if last_nudged_hash == current_hash {
620	        return;
621	    }
622	
623	    let prompt_path = working_directory.join(RENDERED_PROMPT_FILENAME);
624	    let message = format!(
625	        "Your coordinator instructions changed since this session started. Re-read {} now and follow the updated instructions.",
626	        prompt_path.display()
627	    );
628	    match tmux.send_keys(&record.session_name, &message).await {
629	        Ok(()) => {
630	            if let Err(error) = work_db.set_metadata(PROMPT_NUDGE_HASH_KEY, &current_hash) {
631	                // Sent but couldn't persist: leave this to the next
632	                // restart's comparison rather than risk under-reporting a
633	                // sent nudge as a failed one.
634	                let error = format!("{error:#}");
635	                tracing::error!(
636	                    error = %error,
637	                    "coordinator prompt nudge: sent but failed to persist the new hash; will re-nudge next restart"
638	                );
639	                audit::record_event(
640	                    "coordinator_prompt_nudge",
641	                    &json!({
642	                        "outcome": "sent_unpersisted",
643	                        "session_name": record.session_name,
644	                        "error": error,
645	                    }),
646	                );
647	                return;
648	            }
649	            audit::record_event(
650	                "coordinator_prompt_nudge",
651	                &json!({"outcome": "sent", "session_name": record.session_name}),
652	            );
653	            tracing::info!(
654	                session_name = %record.session_name,
655	                "coordinator prompt nudge sent: instructions changed since session start"
656	            );
657	        }
658	        Err(error) => {
659	            audit::record_event(
660	                "coordinator_prompt_nudge",
661	                &json!({
662	                    "outcome": "failed",
663	                    "session_name": record.session_name,
664	                    "error": format!("{error:#}"),
665	                }),
666	            );
667	            tracing::error!(
668	                error = %format!("{error:#}"),
669	                session_name = %record.session_name,
670	                "coordinator prompt nudge: send failed; stored hash left unchanged so the next restart retries"
671	            );
672	        }
673	    }
674	}
