772	/// Compose the session-start handoff brief for a fresh coordinator
773	/// session, persist it under the session directory, and return the shell
774	/// fragment that hands it to `claude` as the positional initial prompt.
775	///
776	/// Never fails session creation. If the brief file cannot be written, the
777	/// fragment is instead a short inline prompt that says so and points the
778	/// session at `boss handoff show` — the incoming session must never start
779	/// silently, as if there were nothing to hand off, because the engine hit
780	/// a filesystem error. Every outcome is audited as
781	/// `coordinator_handoff_brief`.
782	fn prepare_session_start_brief(
783	    work_db: &WorkDb,
784	    working_directory: &Path,
785	    previous: Option<&PreviousSession>,
786	    reason: CoordinatorStartReason,
787	) -> String {
788	    let state = work_db.coordinator_handoff_state();
789	    let now = boss_engine_utils::epoch_time::now_epoch_secs();
790	    let transcript_dir = coordinator_handoff::existing_transcript_dir(working_directory);
791	    let brief = coordinator_handoff::compose_start_brief(StartBriefInputs {
792	        state: &state,
793	        previous,
794	        reason,
795	        now_epoch_secs: now,
796	        transcript_dir: transcript_dir.as_deref(),
797	    });
798	    let (handoff_written_at, written_by_previous) = match &state {
799	        HandoffState::Present(handoff) => (
800	            Some(handoff.written_at),
801	            previous.is_some_and(|p| !p.spawn_token.is_empty() && p.spawn_token == handoff.writer_spawn_token),
802	        ),
803	        _ => (None, false),
804	    };
805	    audit::record_event(
806	        "coordinator_handoff_brief",
807	        &json!({
808	            "outcome": state.audit_outcome(),
809	            "start_reason": reason.audit_label(),
810	            "previous_spawn_token": previous.map(|p| p.spawn_token.as_str()),
811	            "previous_spawned_at": previous.and_then(|p| p.spawned_at),
812	            "handoff_written_at": handoff_written_at,
813	            "handoff_written_by_previous_session": written_by_previous,
814	        }),
815	    );
816	    match coordinator_handoff::write_start_brief(working_directory, &brief) {
817	        Ok(path) => {
818	            tracing::info!(
819	                path = %path.display(),
820	                outcome = state.audit_outcome(),
821	                start_reason = reason.audit_label(),
822	                "coordinator handoff: session-start brief written for the incoming session"
823	            );
824	            format!(
825	                "\"$(cat {})\"",
826	                boss_ssh_transport::shell_quote(&path.to_string_lossy())
827	            )
828	        }
829	        Err(error) => {
830	            let error = format!("{error:#}");
831	            tracing::error!(
832	                error = %error,
833	                "coordinator handoff: could not write the session-start brief; launching with an inline notice instead"
834	            );
835	            audit::record_event(
836	                "coordinator_handoff_brief",
837	                &json!({
838	                    "outcome": "brief_unwritable",
839	                    "handoff_state": state.audit_outcome(),
840	                    "error": error,
841	                }),
842	            );
843	            boss_ssh_transport::shell_quote(&format!(
844	                "[Boss coordinator session start] The engine could not write your session-start handoff brief \
845	                 ({error}). Stored handoff state per the engine: {}. Run `boss handoff show` now to read the \
846	                 stored coordinator handoff, tell the operator in your first reply that the brief could not be \
847	                 written, and follow the \"Session handoff\" section of your instructions.",
848	                state.audit_outcome()
849	            ))
850	        }
851	    }
852	}
