            send_response(
                &sink,
                &request_id,
                FrontendEvent::CoordinatorHandoffSet {
                    handoff: handoff_view(&handoff, current.as_deref(), now),
                },
            );
        }
        Err(err) => {
            tracing::error!(?err, "set_coordinator_handoff failed to persist");
            send_work_error(
                &sink,
                &request_id,
                format!("failed to persist coordinator handoff: {err:#}"),
            );
        }
    }
}

